mkitem!{mkimpl!{impl < 'tcx > TerminatorClassifier < 'tcx > for CallRecursion < 'tcx > { #[doc = " Returns `true` if `func` refers to the function we are searching in."] fn is_recursive_terminator (& self , tcx : TyCtxt < 'tcx > , body : & Body < 'tcx > , terminator : & Terminator < 'tcx > ,) -> bool { let TerminatorKind :: Call { func , args , .. } = & terminator . kind else { return false ; } ; if args . len () != body . arg_count { return false ; } let caller = body . source . def_id () ; let typing_env = body . typing_env (tcx) ; let func_ty = func . ty (body , tcx) ; if let ty :: FnDef (callee , args) = * func_ty . kind () { let Ok (normalized_args) = tcx . try_normalize_erasing_regions (typing_env , args) else { return false ; } ; let (callee , call_args) = if let Ok (Some (instance)) = Instance :: try_resolve (tcx , typing_env , callee , normalized_args) { (instance . def_id () , instance . args) } else { (callee , normalized_args) } ; return callee == caller && & call_args [.. self . trait_args . len ()] == self . trait_args ; } false } }}}
mkitem!{mkimpl!{impl < 'tcx > TerminatorClassifier < 'tcx > for RecursiveDrop < 'tcx > { fn is_recursive_terminator (& self , tcx : TyCtxt < 'tcx > , body : & Body < 'tcx > , terminator : & Terminator < 'tcx > ,) -> bool { let TerminatorKind :: Drop { place , .. } = & terminator . kind else { return false } ; let dropped_ty = place . ty (body , tcx) . ty ; dropped_ty == self . drop_for } }}}
mkitem!{mkimpl!{impl < 'mir , 'tcx , C : TerminatorClassifier < 'tcx > > TriColorVisitor < BasicBlocks < 'tcx > > for Search < 'mir , 'tcx , C > { type BreakVal = NonRecursive ; fn node_examined (& mut self , bb : BasicBlock , prior_status : Option < NodeStatus > ,) -> ControlFlow < Self :: BreakVal > { if let Some (NodeStatus :: Visited) = prior_status { return ControlFlow :: Break (NonRecursive) ; } match self . body [bb] . terminator () . kind { TerminatorKind :: UnwindTerminate (_) | TerminatorKind :: CoroutineDrop | TerminatorKind :: UnwindResume | TerminatorKind :: Return | TerminatorKind :: Unreachable | TerminatorKind :: Yield { .. } => ControlFlow :: Break (NonRecursive) , TerminatorKind :: InlineAsm { ref targets , .. } => { if ! targets . is_empty () { ControlFlow :: Continue (()) } else { ControlFlow :: Break (NonRecursive) } } TerminatorKind :: Assert { .. } | TerminatorKind :: Call { .. } | TerminatorKind :: Drop { .. } | TerminatorKind :: FalseEdge { .. } | TerminatorKind :: FalseUnwind { .. } | TerminatorKind :: Goto { .. } | TerminatorKind :: SwitchInt { .. } => ControlFlow :: Continue (()) , TerminatorKind :: TailCall { .. } => ControlFlow :: Continue (()) , } } fn node_settled (& mut self , bb : BasicBlock) -> ControlFlow < Self :: BreakVal > { let terminator = self . body [bb] . terminator () ; if self . classifier . is_recursive_terminator (self . tcx , self . body , terminator) { self . reachable_recursive_calls . push (terminator . source_info . span) ; } ControlFlow :: Continue (()) } fn ignore_edge (& mut self , bb : BasicBlock , target : BasicBlock) -> bool { let terminator = self . body [bb] . terminator () ; let ignore_unwind = terminator . unwind () == Some (& mir :: UnwindAction :: Cleanup (target)) && terminator . successors () . count () > 1 ; if ignore_unwind || self . classifier . is_recursive_terminator (self . tcx , self . body , terminator) { return true ; } match & terminator . kind { TerminatorKind :: FalseEdge { imaginary_target , .. } => imaginary_target == & target , _ => false , } } }}}